"""Lazy Native actor creation from a reviewed one-way left-turn packet.

No CARLA import occurs here. Caller owns the world and supplies transform_factory.
"""
from __future__ import annotations

import json
import math
from pathlib import Path

from red_left_measurement import validate_site, _number, _xy, _dot, _cross


def _xyz(value, name):
    if not isinstance(value, list) or len(value) != 3:
        raise ValueError("missing xyz " + name)
    return tuple(_number(x, name) for x in value)


def validate_spawn(packet_path, variables=None):
    variables = variables or {}
    approach = variables.get("approach_position", "extreme_left")
    receiving = variables.get("receiving_direction", "one_way_left")
    if approach not in ("extreme_left", "inner_lane"):
        raise ValueError("unsupported requested approach lane")
    site = validate_site(packet_path, receiving)
    packet = json.loads(Path(packet_path).read_text())
    plan = packet.get("spawn_plan")
    if not isinstance(plan, dict) or set(plan) != {"ego", "pedestrians", "other_traffic"}:
        raise ValueError("reviewed spawn plan missing")
    ego = plan["ego"]
    selected_lane = site["left_lane_id"] if approach == "extreme_left" else site["inner_lane_id"]
    if ego.get("lane_id") != selected_lane:
        raise ValueError("ego not in requested approach lane")
    xyz = _xyz(ego.get("location_xyz_m"), "ego")
    rotation = _xyz(ego.get("rotation_rpy_deg"), "ego rotation")
    if not ego.get("source_citation") or not ego.get("blueprint_id"):
        raise ValueError("uncited ego spawn")
    offset = tuple(xyz[i] - site["reference"][i] for i in (0, 1))
    if _dot(offset, site["direction"]) >= site["stop_progress_m"] - 2:
        raise ValueError("ego spawn not upstream of stop reference")
    heading = (math.cos(math.radians(rotation[2])), math.sin(math.radians(rotation[2])))
    if _dot(heading, site["direction"]) < 0.95:
        raise ValueError("ego heading differs from one-way approach")
    for kind in ("pedestrians", "other_traffic"):
        if not isinstance(plan[kind], list):
            raise ValueError("participant list missing")
        for actor in plan[kind]:
            _xyz(actor.get("location_xyz_m"), kind)
            _xyz(actor.get("rotation_rpy_deg"), kind)
            if not actor.get("blueprint_id") or not actor.get("source_citation") or not actor.get("route_source_citation"):
                raise ValueError("uncited participant spawn or route")
            if not isinstance(actor.get("route_points_xyz_m"), list) or len(actor["route_points_xyz_m"]) < 2:
                raise ValueError("participant route missing")
            for point in actor["route_points_xyz_m"]:
                _xyz(point, kind + " route")
    response = variables.get("conflict_response_request", "no_conflict")
    if response.startswith("pedestrian") and not plan["pedestrians"]:
        raise ValueError("requested pedestrian conflict lacks sourced actor")
    if response.startswith("traffic") and not plan["other_traffic"]:
        raise ValueError("requested traffic conflict lacks sourced actor")
    return site, plan


class NativeActors:
    def __init__(self, ego, signal, pedestrians, traffic, owned):
        self.ego, self.signal = ego, signal
        self.pedestrians, self.traffic, self.owned = pedestrians, traffic, owned

    def close(self):
        for actor in reversed(self.owned):
            actor.destroy()
        self.owned.clear()


def create(world, packet_path, transform_factory, variables=None):
    site, plan = validate_spawn(packet_path, variables)
    signals = [actor for actor in world.get_actors() if str(actor.id) == site["signal_actor_id"]]
    if len(signals) != 1:
        raise ValueError("official signal actor absent or ambiguous")
    owned = []
    try:
        library = world.get_blueprint_library()

        def spawn(spec):
            blueprint = library.find(spec["blueprint_id"])
            actor = world.try_spawn_actor(blueprint, transform_factory(_xyz(spec["location_xyz_m"], "spawn"),
                                                                _xyz(spec["rotation_rpy_deg"], "rotation")))
            if actor is None:
                raise ValueError("Native actor spawn failed")
            owned.append(actor)
            return actor

        ego = spawn(plan["ego"])
        pedestrians = [spawn(spec) for spec in plan["pedestrians"]]
        traffic = [spawn(spec) for spec in plan["other_traffic"]]
        return NativeActors(ego, signals[0], pedestrians, traffic, owned)
    except Exception:
        for actor in reversed(owned):
            actor.destroy()
        raise

"""Source-gated control requests for the C153046 red-left comparison attempts.

Commands are requests to a Native adapter. Only original traces can establish
whether a stop, extreme-left position or yield was physically realized.
"""
from __future__ import annotations

import math


def _number(value, name):
    if type(value) not in (int, float) or not math.isfinite(value):
        raise ValueError('observed ' + name + ' missing')
    return float(value)


class RedLeftController:
    def __init__(self, case_id: str, variables: dict, site: dict,
                 approach_hold_margin_m: float = 1.0,
                 yield_release_delay_s: float = 0.0):
        self.case_id = case_id
        self.variables = variables
        self.site = site
        if variables.get('signal_request') != 'steady_red_alone':
            raise ValueError('case signal request unsupported')
        if variables.get('stop_request') not in ('complete_stop', 'rolling'):
            raise ValueError('case stop request unsupported')
        if variables.get('approach_position') not in ('extreme_left', 'inner_lane'):
            raise ValueError('case approach position unsupported')
        if variables.get('receiving_direction') not in ('one_way_left', 'two_way'):
            raise ValueError('case receiving direction unsupported')
        if variables.get('conflict_response_request') not in (
            'no_conflict', 'pedestrian_yield', 'pedestrian_advance',
            'traffic_yield', 'traffic_advance'):
            raise ValueError('case conflict request unsupported')
        if not site.get('source_packet_sha256') or not site.get('signal_actor_id'):
            raise ValueError('reviewed site identity missing')
        if not site.get('left_lane_id') or not site.get('inner_lane_id'):
            raise ValueError('reviewed approach lanes missing')
        if site.get('receiving_direction') != variables['receiving_direction']:
            raise ValueError('receiving road differs from exact case')
        self.approach_hold_margin_m = _number(approach_hold_margin_m, 'approach hold margin')
        if not 0.5 <= self.approach_hold_margin_m <= 3.0:
            raise ValueError('approach hold margin outside tested range')
        self.yield_release_delay_s = _number(yield_release_delay_s, 'yield release delay')
        if not 0.0 <= self.yield_release_delay_s <= 2.0:
            raise ValueError('yield release delay outside tested range')
        self.stop_seen = False
        self.last_conflict_time = None
        self.previous_frame = None
        self.previous_time = None

    def step(self, observation: dict) -> dict:
        """Return one adapter request from one original Native observation."""
        if observation.get('origin') != 'native_world_snapshot':
            raise ValueError('original Native observation missing')
        if observation.get('source_packet_sha256') != self.site['source_packet_sha256']:
            raise ValueError('site packet source changed')
        if str(observation.get('signal_actor_id')) != str(self.site['signal_actor_id']):
            raise ValueError('official signal actor changed')
        if observation.get('signal_state') != 'steady_red_alone':
            raise ValueError('red-alone signal observation missing')
        frame = observation.get('frame')
        time_s = _number(observation.get('time_s'), 'time')
        if type(frame) is not int:
            raise ValueError('original frame missing')
        if self.previous_frame is not None and (
            frame != self.previous_frame + 1 or
            abs(time_s - self.previous_time - 0.05) > 0.001
        ):
            raise ValueError('original 20 Hz sequence broken')
        expected_lane = (self.site['left_lane_id'] if
                         self.variables['approach_position'] == 'extreme_left' else
                         self.site['inner_lane_id'])
        if observation.get('ego_lane_id') != expected_lane:
            raise ValueError('actual approach lane differs from case')
        distance = _number(observation.get('body_front_to_stop_m'), 'body-front distance')
        speed = _number(observation.get('speed_m_s'), 'ego speed')
        if speed < 0:
            raise ValueError('negative ego speed')
        participants = observation.get('directed_participants')
        if not isinstance(participants, list):
            raise ValueError('directed participant inventory missing')
        occupied = set()
        for participant in participants:
            if (participant.get('kind') not in ('pedestrian', 'traffic') or
                type(participant.get('conflict_zone_occupied')) is not bool or
                not participant.get('native_actor_id') or
                not participant.get('source_citation')):
                raise ValueError('directed participant source missing')
            if participant['conflict_zone_occupied']:
                occupied.add(participant['kind'])
        policy = self.variables['conflict_response_request']
        target = 'pedestrian' if policy.startswith('pedestrian') else (
            'traffic' if policy.startswith('traffic') else None)
        if target and not any(p['kind'] == target for p in participants):
            raise ValueError('case conflict participant absent')
        if target in occupied:
            self.last_conflict_time = time_s
        self.previous_frame, self.previous_time = frame, time_s
        if distance > self.approach_hold_margin_m:
            action = 'approach_stop_reference'
        elif not self.stop_seen and self.variables['stop_request'] == 'complete_stop':
            action = 'hold_before_reference'
            if speed <= 0.05 and distance >= 0:
                self.stop_seen = True
        elif target in occupied and policy.endswith('yield'):
            action = 'hold_for_directed_conflict'
        elif (target and policy.endswith('yield') and
              self.last_conflict_time is not None and
              time_s - self.last_conflict_time < self.yield_release_delay_s):
            action = 'hold_for_directed_conflict_release'
        else:
            action = 'turn_left_request'
        return {'case_id': self.case_id, 'native_frame': frame, 'action': action,
                'stop_observed': self.stop_seen,
                'conflict_occupied': sorted(occupied),
                'legal_judgment': 'unresolved',
                'physical_acceptance_claimed': False}

"""Source-bound measurements for the assigned one-way red-left branch.

The output is physical description, never a statutory verdict. A fixture can
test this code but cannot establish that a reviewed CARLA site exists.
"""
from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path


def _number(value, name):
    if type(value) not in (int, float) or not math.isfinite(value):
        raise ValueError("missing finite " + name)
    return float(value)


def _xy(value, name):
    if not isinstance(value, list) or len(value) != 2:
        raise ValueError("missing XY " + name)
    return (_number(value[0], name), _number(value[1], name))


def _dot(a, b):
    return a[0] * b[0] + a[1] * b[1]


def _cross(a, b):
    return a[0] * b[1] - a[1] * b[0]


def _sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def validate_site(packet_path, expected_receiving_direction="one_way_left"):
    """Validate retained source custody and stated lane/stop geometry."""
    packet_path = Path(packet_path).resolve()
    packet = json.loads(packet_path.read_text())
    if packet.get("format") != "c153046-red-left-site-v1" or not packet.get("reviewer"):
        raise ValueError("unreviewed exact site packet")
    sources = packet.get("sources")
    route_source = ("two_way_routes" if expected_receiving_direction == "two_way"
                    else "one_way_routes")
    if not isinstance(sources, dict) or set(sources) != {
        "opendrive", "official_signal", route_source, "stop_reference"
    }:
        raise ValueError("incomplete site source inventory")
    for name, source in sources.items():
        if not isinstance(source, dict) or not source.get("citation") or not source.get("reviewer"):
            raise ValueError("uncited site source: " + name)
        path = (packet_path.parent / source.get("path", "")).resolve()
        if not path.is_relative_to(packet_path.parent) or not path.is_file() or _sha(path) != source.get("sha256"):
            raise ValueError("source bytes missing or changed: " + name)
    if packet.get("approach_one_way") is not True:
        raise ValueError("one-way directions unreviewed")
    if expected_receiving_direction == "one_way_left":
        if packet.get("receiving_one_way_to_left") is not True:
            raise ValueError("one-way receiving direction unreviewed")
    elif expected_receiving_direction == "two_way":
        if packet.get("receiving_two_way") is not True or packet.get("receiving_one_way_to_left") is not False:
            raise ValueError("two-way receiving direction unreviewed")
    else:
        raise ValueError("unsupported receiving direction")
    direction = _xy(packet.get("approach_direction_xy"), "approach direction")
    outgoing = _xy(packet.get("receiving_direction_xy"), "receiving direction")
    if abs(math.hypot(*direction) - 1) > 0.01 or abs(math.hypot(*outgoing) - 1) > 0.01 or _cross(direction, outgoing) < 0.7:
        raise ValueError("receiving route does not turn left")
    reference = _xy(packet.get("approach_reference_xy"), "approach reference")
    lanes = packet.get("approach_lane_centers_xy")
    if not isinstance(lanes, dict) or len(lanes) < 2:
        raise ValueError("distinct approach lanes missing")
    lateral = {key: _cross(direction, tuple(point[i] - reference[i] for i in (0, 1)))
               for key, point in ((key, _xy(value, "lane")) for key, value in lanes.items())}
    extreme = max(lateral, key=lateral.get)
    if packet.get("extreme_left_lane_id") != extreme or len({round(x, 3) for x in lateral.values()}) != len(lateral):
        raise ValueError("extreme-left position unverified")
    signal = packet.get("signal", {})
    if signal.get("official") is not True or signal.get("head_configuration") != "steady_red_alone" or not signal.get("native_actor_id"):
        raise ValueError("official red-alone signal unverified")
    stop = packet.get("stop_reference", {})
    if stop.get("kind") not in {"marked_crosswalk", "signed_or_marked_stop", "intersection_entry"} or stop.get("hierarchy_reviewed") is not True:
        raise ValueError("applicable stop hierarchy unreviewed")
    stop_point = _xy(stop.get("point_xy"), "stop reference")
    inner = sorted(lateral, key=lateral.get, reverse=True)[1]
    return {"source_packet_sha256": _sha(packet_path), "direction": direction,
            "source_hashes": {name: source["sha256"] for name, source in sources.items()},
            "reference": reference, "stop_progress_m": _dot(tuple(stop_point[i] - reference[i] for i in (0, 1)), direction),
            "left_lane_id": extreme, "inner_lane_id": inner,
            "receiving_direction": expected_receiving_direction,
            "signal_actor_id": str(signal["native_actor_id"]),
            "stop_kind": stop["kind"]}


def measure(packet_path, trace_path, case_id, *, expected_receiving_direction="one_way_left",
            expected_approach_position="extreme_left"):
    """Measure a sealed 20 Hz original history without substituting requests."""
    site = validate_site(packet_path, expected_receiving_direction)
    if expected_approach_position not in {"extreme_left", "inner_lane"}:
        raise ValueError("unsupported approach position")
    expected_lane = (site["left_lane_id"] if expected_approach_position == "extreme_left"
                     else site["inner_lane_id"])
    rows = [json.loads(line) for line in Path(trace_path).read_text().splitlines() if line.strip()]
    if len(rows) < 2:
        raise ValueError("original history too short")
    measurements = []
    previous = None
    for row in rows:
        if row.get("case_id") != case_id or row.get("source_packet_sha256") != site["source_packet_sha256"]:
            raise ValueError("case or source identity differs")
        frame = row.get("native_frame", {})
        if frame.get("origin") != "native_world_snapshot" or str(frame.get("signal_actor_id")) != site["signal_actor_id"]:
            raise ValueError("original signal source missing")
        index = frame.get("frame")
        time_s = _number(frame.get("time_s"), "frame time")
        if type(index) is not int or (previous and (index != previous[0] + 1 or abs(time_s - previous[1] - 0.05) > 0.001)):
            raise ValueError("original 20 Hz sequence broken")
        previous = index, time_s
        ego = frame.get("ego", {})
        if ego.get("lane_id") not in {expected_lane, "receiving"}:
            raise ValueError("ego exact approach lane source missing")
        vertices = ego.get("body_vertices_xy")
        if not isinstance(vertices, list) or len(vertices) < 4:
            raise ValueError("full original ego body missing")
        front = max(_dot(tuple(p[i] - site["reference"][i] for i in (0, 1)), site["direction"])
                    for p in (_xy(value, "ego vertex") for value in vertices))
        speed = _number(ego.get("speed_m_s"), "actual ego speed")
        actors = frame.get("directed_participants")
        if not isinstance(actors, list):
            raise ValueError("signal-directed participant inventory missing")
        for actor in actors:
            if not actor.get("native_actor_id") or not isinstance(actor.get("conflict_zone_occupied"), bool) or not actor.get("source_citation"):
                raise ValueError("participant source or conflict missing")
        measurements.append({"frame": index, "time_s": time_s,
                             "red_alone": frame.get("signal_state") == "steady_red_alone",
                             "front_progress_m": front, "actual_speed_m_s": speed,
                             "crossed_stop_reference": front > site["stop_progress_m"],
                             "directed_conflict": any(x["conflict_zone_occupied"] for x in actors)})
    first_entry = next((i for i, x in enumerate(measurements) if x["crossed_stop_reference"]), None)
    prior = measurements if first_entry is None else measurements[:first_entry]
    stops = [x for x in prior if x["actual_speed_m_s"] <= 0.05 and x["red_alone"]]
    conflict_entry = [] if first_entry is None else [x for x in measurements[first_entry:] if x["red_alone"] and x["directed_conflict"]]
    return {"case_id": case_id, "site_sha256": site["source_packet_sha256"],
            "trace_sha256": _sha(trace_path), "original_frames": len(measurements),
            "stop_reference_kind": site["stop_kind"], "extreme_left_lane_id": site["left_lane_id"],
            "source_hashes": site["source_hashes"],
            "expected_approach_lane_id": expected_lane,
            "receiving_direction": expected_receiving_direction,
            "first_entry_frame": None if first_entry is None else measurements[first_entry]["frame"],
            "first_pre_entry_stop_frame": None if not stops else stops[0]["frame"],
            "red_conflict_entry_frames": [x["frame"] for x in conflict_entry],
            "legal_judgment": "unresolved", "physical_acceptance_claimed": False}


def measure_exact(packet_path, trace_path, case_id, plan_path=None):
    """Bind original-frame measurement to the requested exact statutory probe."""
    plan_path = Path(plan_path) if plan_path else Path(__file__).resolve().parent / "case-plan.json"
    plan = json.loads(plan_path.read_text())
    if plan.get("assignment_id") != "testing__C153046__NRS-484B-307-8a__motor_vehicle_driver":
        raise ValueError("exact case plan identity differs")
    matches = [row for row in plan.get("cases", []) if row.get("case_id") == case_id]
    if len(matches) != 1:
        raise ValueError("exact case absent or duplicated")
    variables = matches[0]["draft_variables"]
    result = measure(packet_path, trace_path, case_id,
                     expected_receiving_direction=variables["receiving_direction"],
                     expected_approach_position=variables["approach_position"])
    result["requested_variables"] = variables
    return result

"""Independent saved-metric comparison guard for the red-left attempt pairs."""
from __future__ import annotations


def audit(left, right, expected_left, expected_right):
    for metric, case in ((left, expected_left), (right, expected_right)):
        if metric.get("case_id") != case or metric.get("legal_judgment") != "unresolved":
            raise ValueError("comparison case or legal-state mismatch")
        if metric.get("physical_acceptance_claimed") is not False or metric.get("original_frames", 0) < 2:
            raise ValueError("missing original-frame proof")
        if not metric.get("site_sha256") or not metric.get("trace_sha256"):
            raise ValueError("comparison source binding missing")
        if not metric.get("stop_reference_kind") or not metric.get("extreme_left_lane_id"):
            raise ValueError("comparison fixed geometry missing")
    if left["site_sha256"] != right["site_sha256"] or left["stop_reference_kind"] != right["stop_reference_kind"]:
        raise ValueError("comparison site or stop reference changed")
    if left["trace_sha256"] == right["trace_sha256"]:
        raise ValueError("comparison reuses same original history")
    return {"left_case_id": expected_left, "right_case_id": expected_right,
            "site_sha256": left["site_sha256"], "fixed_stop_reference": left["stop_reference_kind"],
            "requested_difference_physically_confirmed": False,
            "legal_judgment": "unresolved"}


def audit_receiving_direction(one_way, two_way, expected_one_way, expected_two_way):
    """Compare separately reviewed receiving roads with common approach sources."""
    for metric, case, direction, route in (
        (one_way, expected_one_way, "one_way_left", "one_way_routes"),
        (two_way, expected_two_way, "two_way", "two_way_routes"),
    ):
        if (metric.get("case_id") != case or metric.get("receiving_direction") != direction
                or metric.get("legal_judgment") != "unresolved"
                or metric.get("physical_acceptance_claimed") is not False
                or metric.get("original_frames", 0) < 2
                or not metric.get("site_sha256") or not metric.get("trace_sha256")):
            raise ValueError("receiving-direction case or original proof differs")
        hashes = metric.get("source_hashes")
        if not isinstance(hashes, dict) or set(hashes) != {
                "opendrive", "official_signal", "stop_reference", route}:
            raise ValueError("receiving-direction source inventory differs")
        if any(not isinstance(value, str) or len(value) != 64 for value in hashes.values()):
            raise ValueError("receiving-direction source hash missing")
    fixed = ("opendrive", "official_signal", "stop_reference")
    if any(one_way["source_hashes"][key] != two_way["source_hashes"][key] for key in fixed):
        raise ValueError("fixed approach, signal or stop source changed")
    if one_way["trace_sha256"] == two_way["trace_sha256"] or one_way["site_sha256"] == two_way["site_sha256"]:
        raise ValueError("receiving-direction comparison reuses original history or site")
    if one_way.get("stop_reference_kind") != two_way.get("stop_reference_kind"):
        raise ValueError("stop reference kind changed")
    return {"comparison_id": "receiving_direction", "case_ids": [expected_one_way, expected_two_way],
            "fixed_source_sha256": {key: one_way["source_hashes"][key] for key in fixed},
            "one_way_site_sha256": one_way["site_sha256"],
            "two_way_site_sha256": two_way["site_sha256"],
            "requested_difference_physically_confirmed": False,
            "legal_judgment": "unresolved"}
